// WooCommerce's list table script skips rows with the "no-link" class.
function perfectpixel_orders_row_no_link( $classes, $class, $post_id ) {
	if ( is_admin() && 'shop_order' === get_post_type( $post_id ) ) {
		$classes[] = 'no-link';
	}
	return $classes;
}

function perfectpixel_orders_row_no_link_hpos( $classes ) {
	$classes[] = 'no-link';
	return $classes;
}
